import{_ as t,c as a,o as s,a3 as r}from"./chunks/framework.Dokpd4od.js";const d=JSON.parse('{"title":"Project","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/index.md","filePath":"master/services/project/index.md","lastUpdated":1792041590000}'),o={name:"master/services/project/index.md"};function n(i,e,l,h,g,m){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h1><p>Project helps your team plan work, split it into tasks, track time and see progress in one place. A project holds the goal, the people, the dates and the tasks. Everything else in the module supports that.</p><blockquote><p><strong>In simple words:</strong> Switch on the features you need, create a project, add tasks, log hours and read the dashboard.</p></blockquote><p>Open <strong>Project</strong> from the main menu. The top bar shows <strong>Projects</strong>, <strong>Tasks</strong>, <strong>Timesheets</strong>, <strong>Configurations</strong> and <strong>Settings</strong>. The <strong>Dashboard</strong> menu group is separate. It holds a <strong>Project</strong> page.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p>Follow these steps once. Later you only repeat steps 5 to 8.</p><ol><li><strong>Settings.</strong> Choose which features you use: project stages, milestones and timesheets. See <a href="./get-started/project-settings.html">Project settings</a>.</li><li><strong>Stages and tags.</strong> Add project stages and tags. See <a href="./project-management/project-stages-and-milestones.html">Project stages and milestones</a> and <a href="./configuration/tags.html">Tags</a>.</li><li><strong>Project.</strong> Create the project with a customer, a manager and dates. See <a href="./project-management/create-project.html">Create a project</a>.</li><li><strong>Task stages.</strong> Add the task stages of that project. See <a href="./task-management/task-stages-and-states.html">Task stages and states</a>.</li><li><strong>Milestones.</strong> Mark the key points of the project, such as <strong>Phase 1 Complete</strong> and <strong>Go Live</strong>. See <a href="./project-management/project-stages-and-milestones.html">Project stages and milestones</a>.</li><li><strong>Tasks.</strong> Break the work into tasks and sub-tasks. See <a href="./task-management/">Task management</a>.</li><li><strong>Time.</strong> Log the hours people spend. See <a href="./../timesheets/">Timesheets</a>.</li><li><strong>Dashboard.</strong> Read the totals by stage, state, person and project. See <a href="./project-management/project-dashboard.html">Project dashboard</a>.</li></ol><div class="info custom-block"><p class="custom-block-title">Three kinds of &quot;stage&quot; and &quot;state&quot;</p><p>A <strong>project stage</strong> is the phase of a whole project, such as <strong>In Progress</strong>. A <strong>task stage</strong> is a column of one project, such as <strong>Review</strong>. A task <strong>State</strong> says how the task itself stands, such as <strong>Approved</strong>. They are separate. See <a href="./task-management/task-stages-and-states.html">Task stages and states</a>.</p></div><h2 id="running-example" tabindex="-1">Running example <a class="header-anchor" href="#running-example" aria-label="Permalink to &quot;Running example&quot;">​</a></h2><p>The guide follows one project, <strong>Website Revamp</strong>, for the customer <strong>Azure Interiors</strong>. Sales Admin manages it from 01 Jul 2026 to 30 Sep 2026 with 120 allocated hours. It has the milestones <strong>Phase 1 Complete</strong> and <strong>Go Live</strong>. Its tasks include <strong>Design new homepage mockups</strong> and <strong>Migrate CMS content</strong>.</p><h2 id="pages-in-this-module" tabindex="-1">Pages in this module <a class="header-anchor" href="#pages-in-this-module" aria-label="Permalink to &quot;Pages in this module&quot;">​</a></h2><h3 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h3><ul><li><a href="./get-started/">Get started</a></li><li><a href="./get-started/project-settings.html">Project settings</a></li></ul><h3 id="project-management" tabindex="-1">Project management <a class="header-anchor" href="#project-management" aria-label="Permalink to &quot;Project management&quot;">​</a></h3><ul><li><a href="./project-management/">Project management</a></li><li><a href="./project-management/create-project.html">Create a project</a></li><li><a href="./project-management/project-stages-and-milestones.html">Project stages and milestones</a></li><li><a href="./project-management/project-dashboard.html">Project dashboard</a></li></ul><h3 id="task-management" tabindex="-1">Task management <a class="header-anchor" href="#task-management" aria-label="Permalink to &quot;Task management&quot;">​</a></h3><ul><li><a href="./task-management/">Task management</a></li><li><a href="./task-management/create-task.html">Create a task</a></li><li><a href="./task-management/task-stages-and-states.html">Task stages and states</a></li><li><a href="./task-management/task-list-views-and-filters.html">Task list, views and filters</a></li><li><a href="./task-management/sub-tasks.html">Sub tasks</a></li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><ul><li><a href="./configuration/">Configuration</a></li><li><a href="./configuration/tags.html">Tags</a></li><li><a href="./configuration/activity-plans.html">Activity plans</a></li></ul><h3 id="timesheets" tabindex="-1">Timesheets <a class="header-anchor" href="#timesheets" aria-label="Permalink to &quot;Timesheets&quot;">​</a></h3><ul><li><a href="./../timesheets/">Timesheets overview</a></li><li><a href="./../timesheets/log-time.html">Log time</a></li><li><a href="./../timesheets/timesheet-list-and-filters.html">Timesheet list and filters</a></li><li><a href="./../timesheets/timesheet-settings.html">Timesheet settings</a></li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a> for customers</li><li><a href="./../../getting-started/chatter.html">Chatter</a> and <a href="./../../getting-started/activities.html">Activities</a></li><li><a href="./../../general-settings/users/manage-users.html">Manage users</a></li></ul>',23)]))}const p=t(o,[["render",n]]);export{d as __pageData,p as default};
